def independent_paths(training): # Test unseen continuation sequences after all model fitting is complete.
    records=[] # Preserve every separate path-test geometry result.
    for family in ['splice','deck']: # Apply the same validation-only seed selection used for safeguards.
        selected=min((r for r in training if r['family']==family),key=lambda r:r['best_validation_mse']);modeldir=OUT/'models'/family/f"seed_{selected['seed']}";basisdata=np.load(OUT/'models'/family/'basis.npz');basis=basisdata['basis'];scale=float(basisdata['scale']);checkpoint=torch.load(modeldir/'best.pt',weights_only=False);model=Operator(checkpoint['rank']);model.load_state_dict(checkpoint['state_dict']);model.eval() # Restore the exact checkpoint rather than retraining on new paths.
        for index in [11,12,13]: # Preserve held-out geometry identity across both independent sequence tests.
            identity=f'{family}_g{index:02d}_unseen_path';data=dict(np.load(OUT/'cases'/identity/'trajectory.npz'));geometry=torch.tensor(features(data['params']))[None,:].expand(12,-1);q=torch.tensor(data['load_path']*data['params'][4]/data['params'][3],dtype=torch.float32) # Encode the genuinely new signed-load endpoints.
            with torch.no_grad(): coefficients=model(geometry,q).numpy() # Evaluate without any fitting or checkpoint selection.
            prediction=(coefficients*scale@basis.T).reshape(data['displacement'].shape);adapter=FiniteStrain(data['xyz'],data['tet'],data['groups'],float(data['E']),float(data['nu']));residual=[] # Reconstruct every full nodal prediction.
            for j,amplitude in enumerate(data['load_path']): internal,diagnostics=adapter.internal(prediction[j]);residual.append(float(np.linalg.norm((internal.ravel()-data['force']*amplitude)[data['free']])/np.linalg.norm(data['force']))) # Check exact nonlinear free-node force balance at each predicted state.
            evidence=modeldir/f'{identity}_prediction.npz';np.savez_compressed(evidence,prediction=prediction,truth=data['displacement'],load_path=data['load_path'],nonlinear_residual=residual);records.append({'geometry_id':identity,'seed':selected['seed'],'path_relative_L2':float(np.linalg.norm(prediction-data['displacement'])/np.linalg.norm(data['displacement'])),'max_full_nonlinear_residual':max(residual),'endpoint_residuals':residual,'evidence':str(evidence.relative_to(REPO)),'native_evidence':f'build/local-nonlinear-20261024/cases/{identity}/model.dat'}) # Preserve raw held-out path fields and metrics separately from corrected FE results.
