    for axis,family in zip(axes,['splice','deck']): # Draw source-derived tip response and signed forcing.
        data=np.load(OUT/'cases'/f'{family}_g11'/'trajectory.npz');tip=np.argmax(data['xyz'][:,0]);axis.plot(data['load_path'],data['displacement'][:,tip,2],'o-');axis.set(xlabel='Signed peak-load amplitude',ylabel='Tip vertical displacement (mm)',title=f'{family}: native NLGEOM load reversal');axis.grid(alpha=.3) # Preserve exact native state samples without fabricated curves.
    fig.savefig(directory/'native_load_paths.png',dpi=180);fig.savefig(directory/'native_load_paths.pdf');plt.close(fig) # Save reusable raster and vector scientific plots.
    fig,axes=plt.subplots(1,2,figsize=(11,4),constrained_layout=True);labels=[r['geometry_id'] for r in corrections];positions=np.arange(len(labels));axes[0].bar(positions-.2,[r['raw_path_relative_L2'] for r in corrections],.4,label='Raw neural field');axes[0].bar(positions+.2,[r['corrected_path_relative_L2'] for r in corrections],.4,label='After full FE Newton');axes[0].set(yscale='log',ylabel='Trajectory relative L2 error',xticks=positions,xticklabels=labels);axes[0].tick_params(axis='x',rotation=35);axes[0].legend() # Show both error levels while explicitly identifying full FE correction.
