    native=json.loads((OUT/'native_results.json').read_text());additional=json.loads((OUT/'independent_path_native_results.json').read_text());training=json.loads((OUT/'training_results.json').read_text());corrections=json.loads((OUT/'correction_results.json').read_text());refinement=json.loads((OUT/'increment_sensitivity.json').read_text());allnative=native+additional;integrity=[] # Require all expected completed experiment receipts.
